<script setup>
import {computed, onMounted, onBeforeUnmount, ref} from 'vue';
import {api,formatCount,mediaURL} from '../api.js';
import {useStudio} from '../context.js';
import StudioIcon from '../components/StudioIcon.vue';
const studio=useStudio();
const data=ref(null);const failure=ref('');const controller=new AbortController();
const anime=computed(()=>studio.route.value.key==='anime');
const projects=computed(()=>(data.value?.projects || []).filter(project=>(project.mode==='anime_sequel')===anime.value));
const stats=computed(()=>[
  {label:'创作中的作品',value:projects.value.length,icon:'film',note:'每个灵感都有自己的位置'},
  {label:'正在运行',value:projects.value.filter(p=>p.status==='running').length,icon:'activity',note:'任务在后台持续推进'},
  {label:'已就绪作品',value:projects.value.filter(p=>['clean','succeeded'].includes(p.status)).length,icon:'check',note:'保留历史，也保留新可能'},
  {label:'累计模型用量',value:formatCount(projects.value.reduce((sum,p)=>sum+(p.input_tokens||0)+(p.output_tokens||0),0)),icon:'sparkles',note:'Token · 来自真实调用记录'}
]);
const workers=computed(()=>{const value=data.value?.system?.workers?.workers || [];return Array.isArray(value)?value:Object.values(value);});
const statusLabel=value=>({clean:'已就绪',succeeded:'已完成',dirty:'待制作',running:'创作中',failed:'需要处理',queued:'排队中'}[value] || '草稿');
onMounted(async()=>{try{data.value=await api('/dashboard',{signal:controller.signal});}catch(error){if(error.name!=='AbortError')failure.value=error.message;}finally{studio.ready();}});
onBeforeUnmount(()=>controller.abort());
</script>

<template>
  <div class="studio-home">
    <div class="workspace-title"><div><span class="hero-kicker">YOUR NEXT GREAT IDEA</span><h1>{{anime?'给喜欢的世界，写一个新章节。':'今天，想让什么灵感上场？'}}</h1></div><span class="studio-badge"><i/>私人的创作空间</span></div>
    <section class="hero-grid studio-card">
      <div class="hero-copy"><span class="hero-chip"><StudioIcon :name="anime?'sparkles':'music'" :size="16"/>{{anime?'STORY CONTINUES':'THE PERFORMANCE LAB'}}</span><h2 class="hero-title" v-if="!anime">让音乐成形，<br><em>让想象登台。</em></h2><h2 class="hero-title" v-else>下一幕，<br><em>由你来导演。</em></h2><p class="hero-description">{{anime?'上传片段，梳理人物、场景与剧情线索。让导演陪你延续世界观，写出自己的下一集。':'从一段旋律到一支唱跳 MV。挑选声音、规划动作，把你脑海中的舞台，变成可以一步步实现的作品。'}}</p><div class="hero-actions"><button class="studio-button primary" @click="anime?studio.openProject({mode:'anime_sequel'}):studio.navigate('#/performance')">{{anime?'创建动漫续作':'规划我的唱跳作品'}}<StudioIcon name="arrow" :size="18"/></button><button class="studio-button secondary" @click="studio.openProject()">从参考片开始</button></div><div class="hero-footnote"><span><StudioIcon name="shield" :size="14"/>独立授权的人物与声音</span><span><StudioIcon name="layers" :size="14"/>可回退的每一个版本</span></div></div>
      <div class="hero-visual" aria-label="音乐舞台概念插画"><span class="stage-orbit orbit-one"/><span class="stage-orbit orbit-two"/><div class="floating-note note-one"><StudioIcon name="music" :size="20"/><span>Original sound<small>先有一首好歌</small></span><span class="mini-wave"><i/><i/><i/><i/><i/></span></div><div class="stage-figure"><svg viewBox="0 0 360 380" aria-hidden="true"><defs><linearGradient id="dancerFill" x1="0" x2="1" y1="0" y2="1"><stop offset="0" stop-color="var(--accent-a)"/><stop offset="1" stop-color="var(--accent-b)"/></linearGradient></defs><ellipse cx="180" cy="341" rx="119" ry="17" fill="var(--accent-a)" opacity=".14"/><path d="M119 330h122" stroke="var(--accent-a)" opacity=".4" stroke-width="2"/><circle cx="181" cy="76" r="26" fill="url(#dancerFill)"/><path d="m171 111-29 71 37 31 21-81" fill="url(#dancerFill)"/><path d="m160 129-54 21-25-43M194 127l53 29 38-55" fill="none" stroke="url(#dancerFill)" stroke-width="19" stroke-linecap="round"/><path d="m164 203-28 56-38 56m81-111 39 48 31 56" fill="none" stroke="url(#dancerFill)" stroke-width="24" stroke-linecap="round"/><path d="m76 108-8-17m216 10 10-17" stroke="var(--text)" stroke-width="6" stroke-linecap="round"/><path d="m103 322-24 7m165-12 20 7" stroke="var(--text)" stroke-width="13" stroke-linecap="round"/></svg></div><div class="floating-note note-two"><span class="status-orb"/><span>Motion in sync<small>让节奏成为动作</small></span><StudioIcon name="check" :size="16"/></div><div class="stage-caption"><span>IMAGINE · CREATE · PERFORM</span><div class="waveform"><i v-for="n in 25" :key="n" :style="{'--bar':`${12+(n*17)%36}px`,'--delay':`${n*.065}s`}"/></div></div></div>
    </section>
    <div class="metric-grid"><article v-for="stat in stats" :key="stat.label" class="metric-card"><div><span>{{stat.label}}</span><StudioIcon :name="stat.icon" :size="17"/></div><strong>{{stat.value}}</strong><small>{{stat.note}}</small></article></div>
    <section class="home-section"><div class="section-title"><div><span class="hero-kicker">PICK UP WHERE YOU LEFT OFF</span><h2>最近的作品</h2></div><button class="studio-button secondary" @click="studio.openProject({mode:anime?'anime_sequel':'remake'})"><StudioIcon name="plus" :size="16"/>新建作品</button></div><p v-if="failure" class="studio-note error-text">{{failure}}</p><div v-if="projects.length" class="project-cards"><article v-for="project in projects.slice(0,9)" :key="project.id" class="project-tile" @click="studio.navigate(`#/projects/${project.id}/chat`)"><a class="project-thumb" :href="`#/projects/${project.id}/chat`" :aria-label="`打开 ${project.title}`"><img v-if="project.thumbnail_kind==='image'" :src="mediaURL(project.thumbnail_path)" :alt="project.title"/><video v-else-if="project.thumbnail_kind==='video'" :src="mediaURL(project.thumbnail_path)" preload="metadata" muted playsinline/><div v-else class="project-placeholder"><StudioIcon :name="anime?'sparkles':'film'" :size="36"/><span>{{anime?'ANIME STORY':'NEW CREATION'}}</span></div><span class="project-status" :data-status="project.status"><i/>{{statusLabel(project.status)}}</span><span class="project-play"><StudioIcon name="arrow" :size="19"/></span></a><div class="project-meta"><span class="project-kicker">{{anime?'动漫续作':'创作项目'}}</span><h3>{{project.title}}</h3><div><span>{{formatCount((project.input_tokens||0)+(project.output_tokens||0))}} tokens</span><span>继续创作 <StudioIcon name="arrow" :size="13"/></span></div></div></article></div><div v-else class="empty-state studio-card"><StudioIcon name="film" :size="36"/><h3>下一部作品，等你开场。</h3><p>新建项目，或先去演出工作台为第一支 MV 选好方案。</p><button class="studio-button primary" @click="studio.openProject()">创建我的第一部作品</button></div></section>
    <div class="feature-grid"><button class="feature-tile" @click="studio.navigate('#/assets')"><span class="feature-icon"><StudioIcon name="layers" :size="24"/></span><div><h3>属于你的角色与声音</h3><p>把素材整理好，让每次创作都保持一致。</p></div><StudioIcon name="arrow" :size="18"/></button><button class="feature-tile" @click="studio.navigate('#/appearance')"><span class="feature-icon"><StudioIcon name="palette" :size="24"/></span><div><h3>换一种创作心情</h3><p>四套设计语言，找到你喜欢的工作室。</p></div><StudioIcon name="arrow" :size="18"/></button></div>
    <section class="studio-card home-section"><div class="section-title"><h2>工作室状态</h2><a href="#/system">查看全部 <StudioIcon name="arrow" :size="15"/></a></div><div class="activity-list"><div class="activity-item"><span class="activity-symbol"><StudioIcon name="activity" :size="18"/></span><div><strong>生成队列</strong><p>{{workers.filter(worker=>worker.state==='running').length}} 个受管通道正在运行</p></div><a href="#/jobs">查看任务</a></div><div class="activity-item"><span class="activity-symbol"><StudioIcon name="settings" :size="18"/></span><div><strong>模型与工作流</strong><p>连接自己的服务，按需使用 API 或本地 GPU。</p></div><a href="#/settings">管理连接</a></div></div></section>
  </div>
</template>
